// German nutrient database: Max Rubner-Institut (2025): Bundeslebensmittelschlüssel (BLS),
// Version 4.0 — Deutsche Nährstoffdatenbank. Karlsruhe. DOI: 10.25826/Data20251217-134202-0.
// License: CC BY 4.0. bls-4.0.json is generated by scripts/generate-bls-nutrition.ts (ADR 0018).
import type { NutritionValues } from "@yumi/shared";
import rows from "./bls-4.0.json";
import { NUTRIENT_KEYS } from "./format";

export const BLS_SOURCE = "BLS 4.0 (Max Rubner-Institut, CC BY 4.0)";

export type BlsFood = {
  readonly code: string;
  readonly nameDe: string;
  readonly nameEn: string;
  readonly values: NutritionValues;
};

const foods: BlsFood[] = (rows as (string | number)[][]).map(
  ([code, nameDe, nameEn, ...values]) => ({
    code: String(code),
    nameDe: String(nameDe),
    nameEn: String(nameEn),
    values: Object.fromEntries(
      NUTRIENT_KEYS.map((key, i) => [key, Number(values[i])]),
    ) as NutritionValues,
  }),
);
const byCode = new Map(foods.map((food) => [food.code, food]));

export function blsFood(code: string): BlsFood | undefined {
  return byCode.get(code);
}

/** `nutrition_source` text that credits the BLS and names the food. */
export function blsSource(food: BlsFood) {
  return `${BLS_SOURCE}, ${food.code} ${food.nameDe}`;
}

/** Lower-case word stems without accents; strips common German and English plural endings. */
function stems(text: string) {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .split(/[^\p{L}]+/u)
    .filter((word) => word.length >= 3)
    .map((word) =>
      word.length > 4 ? word.replace(/(en|es|e|n|s)$/, "") : word,
    );
}

const PREPARED =
  /gekocht|gebraten|gegart|gebacken|gegrillt|geschmort|gedünstet|gedämpft|frittiert|zubereitet|überbacken|paniert|pochiert|gargezogen/i;

/** Words of the food itself; what follows "mit" or "in" is a side ingredient. */
function mainPart(name: string) {
  return name.split(/\s(?:mit|in|with)\s/)[0] ?? name;
}

const index = foods.map((food) => {
  const main = new Set([
    ...stems(mainPart(food.nameDe)),
    ...stems(mainPart(food.nameEn)),
  ]);
  const all = new Set([...stems(food.nameDe), ...stems(food.nameEn)]);
  return {
    food,
    head: stems(food.nameDe)[0] ?? "",
    words: [...all].map((word) => ({ word, weight: main.has(word) ? 1 : 0.4 })),
    // Codes starting with X or Y are composed dishes.
    penalty:
      (PREPARED.test(food.nameDe) ? 1 : 0) + (/^[XY]/.test(food.code) ? 1 : 0),
    bonus: /\broh\b/.test(food.nameDe) ? 0.5 : 0,
  };
});

function sharedPrefix(a: string, b: string) {
  let i = 0;
  while (i < a.length && a[i] === b[i]) i++;
  return i;
}

/** How well one query word matches one name word; compounds match their parts. */
function termScore(term: string, word: string, head: string) {
  if (term === word) return term === head ? 4 : 3;
  if (word.length >= 4 && term.includes(word)) return 1.5;
  if (term.length >= 4 && word.endsWith(term)) return 2.5;
  if (term.length >= 4 && word.includes(term)) return 1;
  return sharedPrefix(term, word) >= 5 ? 1 : 0;
}

/**
 * BLS foods whose German or English name shares words with the query, as bought
 * before prepared and before dishes. Compounds match their parts ("Kirschtomaten"
 * finds "Tomate roh"). The caller decides whether one of them fits.
 */
export function searchBls(query: string, limit = 12): BlsFood[] {
  const terms = [...new Set(stems(query))];
  if (terms.length === 0) return [];
  const scored: { food: BlsFood; score: number }[] = [];
  for (const entry of index) {
    let score = 0;
    for (const term of terms) {
      let termTotal = 0;
      for (const { word, weight } of entry.words)
        termTotal += weight * termScore(term, word, entry.head);
      score += Math.min(termTotal, 4);
    }
    if (score > 0)
      scored.push({
        food: entry.food,
        score: score - entry.penalty + entry.bonus,
      });
  }
  return scored
    .sort(
      (a, b) =>
        b.score - a.score || a.food.nameDe.length - b.food.nameDe.length,
    )
    .slice(0, limit)
    .map(({ food }) => food);
}
